def count_letters(s):
    counts = {}
    for ch in s:
        counts[ch] = counts.get(ch, 0) + 1
    return counts

print(count_letters("aab"))

def two_sum(nums, target):
    seen = {}
    for i in range(len(nums)):
        need = target - nums[i]
        if need in seen:
            return [seen[need], i]
        seen[nums[i]] = i
    return []

print(two_sum([3, 3], 6))

def most_common(nums):
    counts = {}
    best = None
    best_count = 0
    for x in nums:
        counts[x] = counts.get(x, 0) + 1
        if counts[x] > best_count:
            best = x
            best_count = counts[x]
    return best

print(most_common([1, 2, 2, 1]))

def count_subarrays(nums, target):
    frequency = {0: 1}
    total = 0
    result = 0
    for value in nums:
        total += value
        result += frequency.get(total - target, 0)
        frequency[total] = frequency.get(total, 0) + 1
    return result
